using System.Collections.Generic;public class SnakeGame{int w,h,score;int[][]food;LinkedList<int>b=new();HashSet<int>s=new();public SnakeGame(int width,int height,int[][]food){w=width;h=height;this.food=food;b.AddFirst(0);s.Add(0);}public int Move(string d){int p=b.First.Value,r=p/w,c=p%w;if(d=="U")r--;else if(d=="D")r++;else if(d=="L")c--;else c++;if(r<0||c<0||r>=h||c>=w)return-1;int id=r*w+c;bool eat=score<food.Length&&food[score][0]==r&&food[score][1]==c;if(!eat){s.Remove(b.Last.Value);b.RemoveLast();}if(s.Contains(id))return-1;b.AddFirst(id);s.Add(id);if(eat)score++;return score;}}
